// rtinfo: the default runtime and the runtimes of the Docker daemon behind an endpoint, from its API: GET /info, written as a plain HTTP request.
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"net"
	"net/http"
	"os"
	"sort"
	"strings"
	"time"
)

func fail(code int, format string, a ...any) {
	fmt.Fprintf(os.Stderr, "rtinfo: "+format+"\n", a...)
	os.Exit(code)
}

func main() {
	host := flag.String("host", "", "Docker daemon endpoint: unix:///path/to/docker.sock or tcp://host:port")
	flag.Parse()
	network, addr := "unix", strings.TrimPrefix(*host, "unix://")
	if strings.HasPrefix(*host, "tcp://") {
		network, addr = "tcp", strings.TrimPrefix(*host, "tcp://")
	} else if !strings.HasPrefix(*host, "unix://") {
		fail(2, "--host must be a unix:// or tcp:// endpoint")
	}

	conn, err := net.DialTimeout(network, addr, 10*time.Second)
	if err != nil {
		fail(1, "cannot connect to %s: %v", *host, err)
	}
	defer conn.Close()
	conn.SetDeadline(time.Now().Add(20 * time.Second))
	fmt.Fprint(conn, "GET /info HTTP/1.0\r\nHost: docker\r\nAccept: application/json\r\n\r\n")
	resp, err := http.ReadResponse(bufio.NewReader(conn), nil)
	if err != nil {
		fail(1, "%s did not answer as a Docker daemon: %v", *host, err)
	}
	defer resp.Body.Close()
	var info struct {
		DefaultRuntime string
		Runtimes       map[string]json.RawMessage
	}
	if resp.StatusCode != 200 || json.NewDecoder(resp.Body).Decode(&info) != nil {
		fail(1, "%s did not answer as a Docker daemon (HTTP %d)", *host, resp.StatusCode)
	}

	names := make([]string, 0, len(info.Runtimes))
	for n := range info.Runtimes {
		names = append(names, n)
	}
	sort.Strings(names)
	json.NewEncoder(os.Stdout).Encode(map[string]any{"host": *host, "default_runtime": info.DefaultRuntime, "runtimes": names})
}
